pragma solidity 0.8.20;

import { ERC1967Proxy } from '@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol';
import { Ownable } from '@openzeppelin/contracts/access/Ownable.sol';
import { Address } from '@openzeppelin/contracts/utils/Address.sol';
import { IBlastKandelSeeder, OLKey } from './mangrove/interfaces/IBlastKandelSeeder.sol';
import { IBlastKandel } from './mangrove/interfaces/IBlastKandel.sol';
import { IRangeProtocolMangroveFactory } from './interfaces/IRangeProtocolMangroveFactory.sol';
import { FactoryErrors } from './errors/FactoryErrors.sol';

/**
 * @notice RangeProtocolMangroveFactory deploys and upgrades proxies for Mangrove vaults.
 */
contract RangeProtocolMangroveFactory is IRangeProtocolMangroveFactory, Ownable {
    /// @notice the selector for initialize function on the vault.
    bytes4 public constant INIT_SELECTOR = bytes4(keccak256(bytes('initialize(address,bytes)')));

    /// @notice the selector for upgrading the vault (from UUPS contract version 5 from OZ).
    bytes4 public constant UPGRADE_SELECTOR = bytes4(keccak256(bytes('upgradeToAndCall(address,bytes)')));

    /// @notice address of kandel seeder
    IBlastKandelSeeder immutable _seeder;

    /// @notice address of deployer
    address _deployer;

    /// @notice map of vault to its Kandel.
    mapping(address vault => address kandel) _vaultToKandelMap;

    /// @notice all deployed vault instances
    address[] _vaultsList;

    /**
     * @dev constructor of factory sets the deployer and seeder addresses.
     * @param seeder_ address of the mangrove seeder contract.
     * @param deployer_ address of the deployer.
     */
    constructor(IBlastKandelSeeder seeder_, address deployer_) Ownable(msg.sender) {
        _seeder = seeder_;
        _deployer = deployer_;

        emit DeployerSet(deployer_);
    }

    // @notice createVault creates a ERC1967 proxy instance for the given implementation of vault contract.
    // @param outbound_tkn base/token1 of the vault.
    // @param inbound_tkn quote/token0 of the vault.
    // @param stepSize tick spacing of the vault when it places orders on the kandel.
    // @param implementation address of the implementation.
    // @param data additional data associated with the specific implementation of vault
    function createVault(
        address outbound_tkn,
        address inbound_tkn,
        uint256 stepSize,
        address implementation,
        bytes memory data
    )
        external
        override
        returns (address vault)
    {
        if (msg.sender != _deployer) {
            revert FactoryErrors.OnlyDeployerCanDeployVault();
        }
        address kandel = address(_seeder.sow(OLKey(outbound_tkn, inbound_tkn, stepSize), false));
        vault = _createVault(kandel, implementation, data);
        IBlastKandel(kandel).setAdmin(vault);

        emit VaultCreated(kandel, vault);
    }

    /**
     * @notice upgradeVaults it allows upgrading the implementation contracts for deployed vault proxies.
     * only owner of the factory contract can call it. Internally calls _upgradeVault.
     * @param _vaults list of vaults to upgrade
     * @param _impls new implementation contracts of corresponding vaults
     */
    function upgradeVaults(address[] calldata _vaults, address[] calldata _impls) external override onlyOwner {
        if (_vaults.length != _impls.length) {
            revert FactoryErrors.MismatchedVaultsAndImplsLength();
        }

        for (uint256 i = 0; i < _vaults.length; i++) {
            _upgradeVault(_vaults[i], _impls[i]);
        }
    }

    /**
     * @notice upgradeVault it allows upgrading the implementation contract for deployed vault proxy.
     * only owner of the factory contract can call it. Internally calls _upgradeVault.
     * @param _vault a vault to upgrade
     * @param _impl new implementation contract of corresponding vault
     */
    function upgradeVault(address _vault, address _impl) public override onlyOwner {
        _upgradeVault(_vault, _impl);
    }

    /**
     * @notice allows owner to change deployer address.
     * @param deployer_ the address of the new deployer
     */
    function changeDeployer(address deployer_) external override onlyOwner {
        _deployer = deployer_;
        emit DeployerSet(deployer_);
    }

    /**
     * @notice returns the vaults addresses based on the provided indexes
     * @param startIdx the index in vaults to start retrieval from.
     * @param endIdx the index in vaults to end retrieval from.
     * @return vaultList list of fetched vault addresses
     */
    function getVaultAddresses(
        uint256 startIdx,
        uint256 endIdx
    )
        external
        view
        override
        returns (address[] memory vaultList)
    {
        vaultList = new address[](endIdx - startIdx + 1);
        for (uint256 i = startIdx; i <= endIdx; i++) {
            vaultList[i - startIdx] = _vaultsList[i];
        }
    }

    /// @notice vaultCount counts the total number of vaults in existence
    /// @return total count of vaults
    function vaultCount() external view override returns (uint256) {
        return _vaultsList.length;
    }

    /// @notice returns the address of mangrove seeder.
    function seeder() external view returns (IBlastKandelSeeder) {
        return _seeder;
    }

    /// @notice returns the address of the deployer.
    function deployer() external view returns (address) {
        return _deployer;
    }

    /// @notice returns the address of Kandel against the vault.
    function vaultToKandelMap(address vault) external view returns (address kandel) {
        return _vaultToKandelMap[vault];
    }

    /**
     * @dev Internal function to create vault proxy.
     */
    function _createVault(address kandel, address implementation, bytes memory data) internal returns (address vault) {
        vault = address(new ERC1967Proxy(implementation, abi.encodeWithSelector(INIT_SELECTOR, kandel, data)));
        _vaultsList.push(vault);
        _vaultToKandelMap[vault] = kandel;
    }

    /**
     * @dev Internal function to upgrade a vault's implementation.
     */
    function _upgradeVault(address _vault, address _impl) internal {
        (bool success,) = _vault.call(abi.encodeWithSelector(UPGRADE_SELECTOR, _impl, ''));

        if (!success) revert FactoryErrors.VaultUpgradeFailed();
        emit VaultImplUpgraded(_vault, _impl);
    }
}

